Identify the GBP-EUR row for each pricedate in TABLE 1.  
For each row in F5:F19, divide the row's GBP midrate by the GBP-EUR midrate for that same date.  
Write the resulting numeric values into F5:F19.

```python
import shutil
import openpyxl
from datetime import datetime, date

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

ws = wb["Sheet1"] if "Sheet1" in wb.sheetnames else wb.active
vals_ws = vals["Sheet1"] if "Sheet1" in vals.sheetnames else vals.active

try:
    from openpyxl.utils.datetime import from_excel
except Exception:
    from_excel = None

def norm_date(v):
    if isinstance(v, datetime):
        return v.date()
    if isinstance(v, date):
        return v
    if isinstance(v, str):
        s = v.strip()
        for fmt in ("%Y-%m-%d %H:%M:%S", "%Y-%m-%d", "%d/%m/%Y %H:%M:%S", "%d/%m/%Y"):
            try:
                return datetime.strptime(s, fmt).date()
            except ValueError:
                pass
    if isinstance(v, (int, float)) and not isinstance(v, bool) and from_excel is not None:
        try:
            return from_excel(v).date()
        except Exception:
            pass
    return v

base_rows = {}
for r in range(5, 20):
    cur = vals_ws.cell(r, 1).value
    if cur is not None and str(cur).strip() == "GBP-EUR":
        d = norm_date(vals_ws.cell(r, 3).value)
        base_rows[d] = r

print("base_rows:", base_rows)

for r in range(5, 20):
    d = norm_date(vals_ws.cell(r, 3).value)
    b = base_rows.get(d)

    # Fallback to the fixed 5-row block structure if date matching fails.
    if b is None:
        b = ((r - 5) // 5) * 5 + 8

    num = vals_ws.cell(r, 2).value
    den = vals_ws.cell(b, 2).value

    if num is None or den is None or den == 0:
        out_val = None
    else:
        out_val = float(num) / float(den)

    ws.cell(r, 6).value = out_val
    print(r, d, b, out_val)

wb.save(OUT)
